240	                      const txIndex = timelineItems.findIndex((item) => {
241	                        if (!item) return false;
242	                        return getItemUniqueKey(item) === txId;
243	                      });
244	                      if (txIndex !== -1) {
245	                        timelineItems[txIndex] = ev;
246	                      }
247	                    }
248	                  }
249	                  break;
250	                }
251	                case TimelineDiff_Tags.Remove: {
252	                  const { index: removeIndex } = diff.inner;
253	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
254	                    timelineItems.splice(removeIndex, 1);
255	                  }
256	                  break;
257	                }
258	                case TimelineDiff_Tags.PushFront: {
259	                  const { value } = diff.inner;
260	                  timelineItems.unshift(toEventItem(value));
261	                  break;
262	                }
263	                case TimelineDiff_Tags.PushBack: {
264	                  const { value } = diff.inner;
265	                  const ev = toEventItem(value);
266	                  timelineItems.push(ev);
267	                  if (ev) {
268	                    const txId = getTransactionId(ev);
269	                    if (txId) {
270	                      pendingTransactionIdsQueue.current.push(txId);
271	                    }
272	                  }
273	                  break;
274	                }
275	                case TimelineDiff_Tags.PopFront: {
276	                  timelineItems.shift();
277	                  break;
278	                }
279	                case TimelineDiff_Tags.PopBack: {
280	                  timelineItems.pop();
281	                  break;
282	                }
283	                case TimelineDiff_Tags.Reset: {
284	                  const resetItems = diff.inner.values;
285	                  pendingTransactionIdsQueue.current = [];
286	                  timelineItemsRef.current = resetItems.map(toEventItem);
287	
288	                  const eventItems = timelineItemsRef.current.filter(
289	                    (i): i is EventTimelineItem => !!i,
290	                  );
291	                  pendingTransactionIdsQueue.current = eventItems
292	                    .map(getTransactionId)
293	                    .filter((id): id is string => !!id);
294	                  break;
295	                }
296	                case TimelineDiff_Tags.Truncate: {
297	                  const { length: cut } = diff.inner;
298	                  timelineItems.length = cut;
299	                  break;
300	                }
301	                case TimelineDiff_Tags.Clear: {
