324	              console.log(
325	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
326	              );
327	            }
328	
329	          },
330	        });
331	
332	        // The SDK delivers cached items via a Reset diff when the listener
333	        // attaches. If the cache is empty (or thin), paginate once to fill
334	        // at least TIMELINE_PAGE_SIZE events from the server.
335	        setTimeout(() => {
336	          const cachedCount = timelineItemsRef.current.length;
337	          console.log(
338	            `[TimelineDebug][${roomId}] initial check: cachedCount=${cachedCount}, threshold=${TIMELINE_PAGE_SIZE}`,
339	          );
340	          if (cachedCount < TIMELINE_PAGE_SIZE) {
341	            console.log(`[TimelineDebug][${roomId}] cache thin — triggering eager pagination`);
342	            loadMoreMessages();
343	          } else {
344	            console.log(`[TimelineDebug][${roomId}] cache sufficient — skipping eager pagination`);
345	          }
346	        }, 0);
347	      } catch (error) {
348	        console.error("Failed to initialize room timeline:", error);
349	        offlineToastHelper("Failed to load the messages. Please try again.");
350	        NavigationContainerRef.goBack();
351	        return null;
352	      }
353	    };
354	
355	    initRoomTimeline();
356	
357	    return () => {
358	      timelineListenerHandle?.cancel?.();
359	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
360	      timelineRef.current = null;
361	      timelineItemsRef.current = [];
362	      isPaginatingRef.current = false;
363	      reachedStartRef.current = false;
364	    };
365	  }, [rebuildEventsFromTimelineItems, room, roomId]);
366	
367	  useEffect(() => {
368	    markAsRead().catch(console.error);
369	    room?.isDirect().then(setIsDirect).catch(console.error);
370	  }, [room, markAsRead]);
371	
372	  return {
373	    events,
374	    timelineRef,
375	    isPaginatingRef,
376	    reachedStartRef,
377	    isDirect,
378	    loadMoreMessages,
379	    markAsRead,
